//! Convert authenticated progress plus independent Root-approved files into
//! actual one-shot host commands. No peer payload approves a Root scope.

use super::*;
use super::files::OriginalFile;
use crate::same_actor_q24_deployment_protocol::OriginalDeploymentProgress;
use crate::same_actor_q24_deployment_protocol::OriginalDeploymentRequest;

pub(super) fn apply_original_progress(
    files: &DeploymentFiles,
    request: &OriginalDeploymentRequest,
    commands: &mpsc::SyncSender<RootSameActorHostCommandV1>,
    acknowledgements: &mpsc::Receiver<RootSameActorHostAcknowledgementV1>,
    gate: &Arc<SameActorPhaseGate>,
    dispatched: &mut bool,
) -> io::Result<Option<String>> {
    let mut closing = CloseSameActorPhaseOnDrop::new(gate);
    files.require_deployment_files()?;
    gate.require_open()?;
    let result = match &request.progress {
        OriginalDeploymentProgress::InputsOpened => {
            let (initial, artifacts) =
                files.initial.original_phase_initial_inputs(files.consumer_uid)?;
            files.require_deployment_files()?;
            require_artifact_files(&artifacts)?;
            send_original_command(
                commands, RootSameActorHostCommandV1::Initial(initial), gate, dispatched,
            )?;
            (|| {
                let binding = require_original_acknowledgement(
                    receive_original_acknowledgement(acknowledgements, gate)?,
                    DeploymentStage::Initial,
                )?;
                files.require_deployment_files()?;
                require_artifact_files(&artifacts)?;
                gate.require_open()?;
                Ok(binding)
            })().map_err(|error| deployment_uncertain("original Initial host command", error))
        }
        OriginalDeploymentProgress::OriginalAPrepared { profile: observed } => {
            // The daemon supplies its actual Prepared observation, never Root
            // approval. Missing or unequal Root0600 material refuses this
            // request immediately; it is not a wait with a renewed deadline.
            let (profile_file, bytes) = MetadataFile::open_metadata(&files.data.learning_profile)?;
            let profile: crate::HostAuthorityLearningProfileV1 =
                serde_json::from_slice(&bytes).map_err(io::Error::other)?;
            if serde_json::to_vec(&profile).map_err(io::Error::other)?
                != serde_json::to_vec(observed).map_err(io::Error::other)?
            {
                return Err(io::Error::other("actual Prepared differs from the Root-approved profile"));
            }
            files.require_deployment_files()?;
            profile_file.require_metadata_unchanged()?;
            send_original_command(
                commands, RootSameActorHostCommandV1::Scoped(profile), gate, dispatched,
            )?;
            (|| {
                let binding = require_original_acknowledgement(
                    receive_original_acknowledgement(acknowledgements, gate)?,
                    DeploymentStage::Scoped,
                )?;
                files.require_deployment_files()?;
                profile_file.require_metadata_unchanged()?;
                gate.require_open()?;
                Ok(binding)
            })().map_err(|error| deployment_uncertain("original scoped host command", error))
        }
        OriginalDeploymentProgress::OriginalSelectionReady { canonical_material } => {
            let bytes = canonical_material.as_bytes();
            let (current, observation) = files.current.original_current_phase_inputs(
                &files.current_directory, files.consumer_uid,
                Digest32::of_bytes(bytes), bytes,
            )?;
            files.require_deployment_files()?;
            files.current.require_current_phase_observation(&observation)?;
            send_original_command(
                commands, RootSameActorHostCommandV1::Current(current), gate, dispatched,
            )?;
            (|| {
                let binding = require_original_acknowledgement(
                    receive_original_acknowledgement(acknowledgements, gate)?,
                    DeploymentStage::Current,
                )?;
                files.require_deployment_files()?;
                files.current.require_current_phase_observation(&observation)?;
                gate.require_open()?;
                Ok(binding)
            })().map_err(|error| deployment_uncertain("original Current host command", error))
        }
    }?;
    gate.require_open()?;
    closing.disarm();
    Ok(result)
}

fn send_original_command(
    sender: &mpsc::SyncSender<RootSameActorHostCommandV1>,
    command: RootSameActorHostCommandV1,
    gate: &Arc<SameActorPhaseGate>,
    dispatched: &mut bool,
) -> io::Result<()> {
    gate.require_open()?;
    sender.try_send(command)
        .map_err(|_| io::Error::other("original phase command queue is full or closed"))?;
    // Set only after the actual transfer. A lost response now remains uncertain
    // and cannot cause this command or its capability to be sent again.
    *dispatched = true;
    gate.notify_original_waiters();
    gate.require_open()
        .map(|_| ())
        .map_err(|error| deployment_uncertain("original Root command handoff", error))
}

pub(super) fn receive_original_acknowledgement(
    receiver: &mpsc::Receiver<RootSameActorHostAcknowledgementV1>,
    gate: &Arc<SameActorPhaseGate>,
) -> io::Result<RootSameActorHostAcknowledgementV1> {
    let mut closing = CloseSameActorPhaseOnDrop::new(gate);
    loop {
        let epoch = gate.original_wait_epoch()?;
        match receiver.try_recv() {
            Ok(value) => {
                gate.require_open()?;
                closing.disarm();
                return Ok(value);
            }
            Err(mpsc::TryRecvError::Empty) => gate.wait_original_change(epoch)?,
            Err(mpsc::TryRecvError::Disconnected) => {
                return Err(io::Error::other("original phase acknowledgement channel closed"));
            }
        }
    }
}

pub(super) fn require_original_acknowledgement(
    acknowledgement: RootSameActorHostAcknowledgementV1,
    stage: DeploymentStage,
) -> io::Result<Option<String>> {
    match (stage, acknowledgement) {
        (DeploymentStage::Initial, RootSameActorHostAcknowledgementV1::InitialRegistered { binding })
        | (DeploymentStage::Current, RootSameActorHostAcknowledgementV1::CurrentRegistered { binding }) => {
            let digest = binding.parse::<Digest32>().map_err(io::Error::other)?;
            if digest.is_zero() {
                return Err(io::Error::other("original registration acknowledgement binding missing"));
            }
            Ok(Some(binding))
        }
        (DeploymentStage::Scoped, RootSameActorHostAcknowledgementV1::ScopedRightsSent) => Ok(None),
        _ => Err(io::Error::other("original phase acknowledgement arrived out of order")),
    }
}

fn require_artifact_files(files: &[OriginalFile]) -> io::Result<()> {
    for file in files {
        file.require_original_file()?;
    }
    Ok(())
}

//! Same-phase access to the original Initial deployment reader. These methods
//! expose pinned material only; registration still consumes the real Root cap.

use super::RootGenerationInitialDeploymentFilesV1;
use super::inputs::InitialOriginalFiles;
use super::shared_files::OriginalFile;
use codex_hepta_contracts::RootAuthorityDirectory;
use codex_hepta_types::Digest32;
use std::io;
use std::path::Path;
use std::sync::Arc;

impl RootGenerationInitialDeploymentFilesV1 {
    pub(in crate::authority_host_runtime::session) fn original_phase_initial_current(
        &self,
    ) -> io::Result<Arc<RootAuthorityDirectory>> {
        self.require_original_initial_files()?;
        if !matches!(self.data.mode, crate::RootGenerationInitialModeV1::Reserve) {
            return Err(io::Error::other("fresh phase requires original Initial Reserve mode"));
        }
        Ok(Arc::clone(&self.inputs.current))
    }

    pub(in crate::authority_host_runtime::session) fn original_phase_initial_current_path(
        &self,
    ) -> &Path {
        &self.data.current_directory
    }

    pub(in crate::authority_host_runtime::session) fn original_phase_initial_consumer_root(
        &self,
    ) -> &Path {
        &self.data.consumer_state_root
    }

    pub(in crate::authority_host_runtime::session) fn original_phase_initial_trigger(
        &self,
    ) -> &Path {
        &self.data.trigger
    }

    pub(in crate::authority_host_runtime::session) fn original_phase_initial_digest(
        &self,
    ) -> Digest32 {
        self.descriptor.digest()
    }

    pub(in crate::authority_host_runtime::session) fn original_phase_initial_inputs(
        &self,
        consumer_uid: u32,
    ) -> io::Result<(crate::RootGenerationInitialEnrollmentV1, Vec<OriginalFile>)> {
        self.require_original_initial_files()?;
        let original: &InitialOriginalFiles = &self.inputs;
        let inputs = original.initial_enrollment_inputs(&self.data, consumer_uid)?;
        self.require_original_initial_files()?;
        Ok(inputs)
    }

    pub(in crate::authority_host_runtime::session) fn require_original_phase_initial_files(
        &self,
    ) -> io::Result<()> {
        self.require_original_initial_files()
    }
}

//! One phase's retained Current descriptor and late original material.
//! No capability or mutable owner is reconstructed from these Root files.

use super::data::DeploymentData;
use super::data::LateMaterial;
use super::data::Mode;
use super::files;
use super::files::DirectoryPin;
use super::files::MetadataFile;
use super::files::OriginalFile;
use super::inputs::OriginalInputs;
use codex_hepta_contracts::RootAuthorityDirectory;
use codex_hepta_types::Digest32;
use std::io;
use std::path::Path;
use std::sync::Arc;

pub(in crate::authority_host_runtime::session) struct OriginalCurrentPhaseFiles {
    descriptor: MetadataFile,
    data: DeploymentData,
    directories: Vec<DirectoryPin>,
}

/// Retained only until the actual one-shot registration and its post-checks.
// The actual command receives clones of these original descriptors.
pub(in crate::authority_host_runtime::session) struct OriginalCurrentPhaseObservation {
    inputs: OriginalInputs,
    material: MetadataFile,
    artifacts: Vec<OriginalFile>,
}

impl OriginalCurrentPhaseFiles {
    pub(in crate::authority_host_runtime::session) fn open_current_phase_descriptor(
        path: &Path,
        current_path: &Path,
        consumer_root: &Path,
    ) -> io::Result<Self> {
        crate::authority_host_service::generation_publication::original_root()?;
        let (descriptor, bytes) = MetadataFile::open_metadata(path)?;
        let data: DeploymentData = serde_json::from_slice(&bytes).map_err(io::Error::other)?;
        if data.schema_version != 1
            || data.issuer_keys.is_empty()
            || !matches!(data.mode, Mode::Reserve)
            || data.current_directory != current_path
            || data.consumer_state_root != consumer_root
            || data.late_material == data.trigger
            || data.trigger == path
            || data.late_material == path
        {
            return Err(io::Error::other(
                "same original phase Current locations and Reserve mode required",
            ));
        }
        let directories = vec![
            DirectoryPin::capture_root(files::parent(&data.trigger)?)?,
            DirectoryPin::capture_root(files::parent(&data.late_material)?)?,
            DirectoryPin::capture_root(&data.current_directory)?,
            DirectoryPin::capture_private(&data.artifact_root)?,
            DirectoryPin::capture_private(&data.consumer_state_root)?,
        ];
        files::require_absolute(&data.trigger)?;
        files::require_absolute(&data.late_material)?;
        let original = Self { descriptor, data, directories };
        original.require_current_phase_files()?;
        Ok(original)
    }

    pub(in crate::authority_host_runtime::session) fn current_phase_descriptor_digest(
        &self,
    ) -> Digest32 {
        self.descriptor.digest()
    }

    pub(in crate::authority_host_runtime::session) fn current_phase_trigger(&self) -> &Path {
        &self.data.trigger
    }

    pub(in crate::authority_host_runtime::session) fn current_phase_material(&self) -> &Path {
        &self.data.late_material
    }

    pub(in crate::authority_host_runtime::session) fn require_current_phase_files(
        &self,
    ) -> io::Result<()> {
        self.descriptor.require_metadata_unchanged()?;
        for directory in &self.directories {
            directory.require_directory()?;
        }
        Ok(())
    }

    pub(in crate::authority_host_runtime::session) fn original_current_phase_inputs(
        &self,
        current: &Arc<RootAuthorityDirectory>,
        consumer_uid: u32,
        material_digest: Digest32,
        observed_material: &[u8],
    ) -> io::Result<(crate::RootGenerationPublicationEnrollmentV1, OriginalCurrentPhaseObservation)> {
        self.require_current_phase_files()?;
        let (material_file, bytes) = MetadataFile::open_metadata(&self.data.late_material)?;
        let material: LateMaterial = serde_json::from_slice(&bytes).map_err(io::Error::other)?;
        if serde_json::to_vec(&material).map_err(io::Error::other)? != bytes
            || material_file.digest() != material_digest
            || bytes != observed_material
        {
            return Err(io::Error::other(
                "phase trigger does not bind the original canonical Current material",
            ));
        }
        // Target journals need not exist at startup. They are opened once here,
        // after the host has supplied the actual selected target, and pinned
        // through the real registration acknowledgement.
        let original = OriginalInputs {
            current: Arc::clone(current),
            previous_journal: OriginalFile::open_original(&self.data.previous_journal)?,
            previous_witness: OriginalFile::open_original(&self.data.previous_witness)?,
            target_journal: OriginalFile::open_original(&self.data.target_journal)?,
            target_witness: OriginalFile::open_original(&self.data.target_witness)?,
            withdrawal: OriginalFile::open_original(&self.data.withdrawal_file)?,
        };
        let (inputs, artifacts) = original.enrollment_inputs(
            &self.data, &material, consumer_uid,
        )?;
        let observation = OriginalCurrentPhaseObservation {
            inputs: original, material: material_file, artifacts,
        };
        self.require_current_phase_observation(&observation)?;
        Ok((inputs, observation))
    }

    pub(in crate::authority_host_runtime::session) fn require_current_phase_observation(
        &self,
        observation: &OriginalCurrentPhaseObservation,
    ) -> io::Result<()> {
        self.require_current_phase_files()?;
        observation.inputs.require_original_inputs()?;
        observation.material.require_metadata_unchanged()?;
        for artifact in &observation.artifacts {
            artifact.require_original_file()?;
        }
        Ok(())
    }
}

