#[test]
fn lost_actual_ack_channel_closes_the_same_retained_endpoint() -> io::Result<()> {
    let gate = gate()?;
    let (stream, mut peer) = UnixStream::pair()?;
    let _retained = gate.retain_original_stream(&stream)?;
